def resource_path(relative_path): # pyright: ignore[reportMissingParameterType, reportUnknownParameterType]
    try:
        base_path = sys._MEIPASS # pyright: ignore[reportUnknownMemberType, reportAttributeAccessIssue, reportUnknownVariableType]
    except Exception:
        base_path = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(base_path, relative_path) # pyright: ignore[reportUnknownArgumentType]
        
def extra_resource_path(relative_path): # pyright: ignore[reportMissingParameterType, reportUnknownParameterType]
    try:
        base_path = sys._MEIPASS # pyright: ignore[reportAttributeAccessIssue, reportUnknownMemberType, reportUnknownVariableType]
    except Exception:
        base_path = os.path.abspath(".")
    return os.path.join(base_path, relative_path) # pyright: ignore[reportUnknownArgumentType]

def get_app_directory():
    if getattr(sys, "frozen", False):
        if os.name != "nt":
            if sys.platform == "darwin":
                user_dir = os.path.expanduser(os.path.join("~/Library/Application Support", APP_NAME))
            else:
                config_root = os.environ.get("XDG_CONFIG_HOME") or os.path.expanduser("~/.config")
                user_dir = os.path.join(config_root, APP_NAME)

            os.makedirs(user_dir, exist_ok=True)
            return user_dir

        return os.path.dirname(os.path.abspath(sys.executable))
    return os.path.dirname(os.path.abspath(__file__))

def developer_log(message: Any) -> None:
    if not DEVELOPER_LOG_FILE:
        return

    try:
        with open(DEVELOPER_LOG_FILE, "a", encoding="utf-8") as file_handle:
            file_handle.write(f"[{datetime.datetime.now().isoformat(timespec='seconds')}] {message}\n")
    except Exception:
        pass

class DeveloperLogStream:
    def __init__(self, original_stream, stream_name): # pyright: ignore[reportUnknownParameterType, reportMissingParameterType]
        self.original_stream = original_stream
        self.stream_name = stream_name

    def write(self, text): # pyright: ignore[reportMissingParameterType, reportUnknownParameterType]
        self.original_stream.write(text) # pyright: ignore[reportUnknownMemberType]
        if not text or not DEVELOPER_LOG_FILE:
            return
        try:
            with open(DEVELOPER_LOG_FILE, "a", encoding="utf-8") as file_handle:
                file_handle.write(text) # pyright: ignore[reportUnknownArgumentType]
        except Exception:
            pass

    def flush(self):
        self.original_stream.flush() # pyright: ignore[reportUnknownMemberType]

    def isatty(self): # pyright: ignore[reportUnknownParameterType]
        return self.original_stream.isatty() # pyright: ignore[reportUnknownMemberType, reportUnknownVariableType]

def initialize_developer_logging() -> None:
    global DEVELOPER_LOG_FILE, DEVELOPER_LOG_STREAMS_INSTALLED
    if not DEVELOPER_MODE or DEVELOPER_LOG_FILE:
        return

    timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
    error_folder = os.path.join(get_app_directory(), "Error Log")
    os.makedirs(error_folder, exist_ok=True)
    DEVELOPER_LOG_FILE = os.path.join(error_folder, f"Error_Developing_{timestamp}.txt") # pyright: ignore[reportConstantRedefinition]

    header = (
        f"Developer diagnostics started: {timestamp}\n"
        f"App: {APP_NAME} {APP_VERSION} {SNAPSHOT_BUILD}\n"
        f"Python: {sys.version}\n"
        f"Executable: {sys.executable}\n"
        f"Platform: {sys.platform} / os.name={os.name}\n"
        f"Working directory: {os.getcwd()}\n"
        f"App directory: {get_app_directory()}\n"
        f"Frozen: {getattr(sys, 'frozen', False)}\n"
        f"DEBUG_TEST: {DEBUG_TEST}\n"
        f"DEVELOPER_MODE: {DEVELOPER_MODE}\n"
        f"Network check: {check_internet()}\n"
        "------------------------------------------------------------\n"
    )
    with open(DEVELOPER_LOG_FILE, "w", encoding="utf-8") as file_handle:
        file_handle.write(header)

    if not DEVELOPER_LOG_STREAMS_INSTALLED:
        sys.stdout = DeveloperLogStream(sys.stdout, "stdout")
        sys.stderr = DeveloperLogStream(sys.stderr, "stderr")
        DEVELOPER_LOG_STREAMS_INSTALLED = True

    def log_uncaught_exception(exc_type, exc_value, exc_traceback): # pyright: ignore[reportUnknownParameterType, reportMissingParameterType]
        developer_log("Uncaught exception:\n" + "".join(traceback.format_exception(exc_type, exc_value, exc_traceback))) # pyright: ignore[reportUnknownArgumentType]
        sys.__excepthook__(exc_type, exc_value, exc_traceback) # pyright: ignore[reportUnknownArgumentType]

    sys.excepthook = log_uncaught_exception

    if hasattr(threading, "excepthook"):
        original_threading_excepthook = threading.excepthook

        def log_thread_exception(args: threading.ExceptHookArgs):
            developer_log(
                f"Uncaught thread exception in {getattr(args.thread, 'name', 'unknown')}:\n"
                + "".join(traceback.format_exception(args.exc_type, args.exc_value, args.exc_traceback))
            )
            original_threading_excepthook(args)

        threading.excepthook = log_thread_exception

    print(f"- Developer diagnostics log: {DEVELOPER_LOG_FILE}")
    
def log_error(error_message: Any) -> None:
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
    log_folder = os.path.join(get_app_directory(), "Error Log")
    os.makedirs(log_folder, exist_ok=True)

    log_filename = f"error_log_{timestamp}.txt"
    log_path = os.path.join(log_folder, log_filename)
    with open(log_path, "w", encoding="utf-8") as f:
        f.write(f"Timestamp: {timestamp}\n")
        f.write(f"App version: {APP_VERSION}\n")
        f.write(f"Error Message: {error_message}\n")
        f.write(f"Operating System: {os.name}\n\n")
        f.write("\nTraceback:\n")
        f.write(traceback.format_exc() or "No traceback available.\n")

    if DEVELOPER_MODE and DEVELOPER_LOG_FILE:
        developer_log(f"ERROR: {error_message}")
        developer_log("Traceback:")
        developer_log(traceback.format_exc() or "No traceback available.")
        print(f"Error logged to {log_path} and developer diagnostics file {DEVELOPER_LOG_FILE}")
    else:
        developer_log(f"ERROR: {error_message}")
        print(f"Error logged to {log_path}")

