def check_internet():
    try:
        socket.create_connection(("8.8.8.8", 53), timeout=3)
        return True
    except OSError:
        return False

def run_update_check():
    global OFFLINE_MODE
    if DEBUG_TEST:
        print("------------------------------------------------")
        print(f">>> DEBUGGING: {APP_NAME} <<<")
        print(f">>> App Version: {APP_VERSION} <<<")
        print(f">>> Debug Mode: {DEBUG_TEST} <<<")
        print(f">>> Snapshot Build: {SNAPSHOT_BUILD} <<<")
        print(f">>> URL: {VersionDetectionURL} <<<")
        print("------------------------------------------------")
        return
    elif DEVELOPER_MODE:
        print("------------------------------------------------")
        print(f">>> DEVELOPING: {APP_NAME} <<<")
        print(f">>> App Version: {APP_VERSION} <<<")
        print(f">>> Snapshot Build: {SNAPSHOT_BUILD} <<<")
        print(f">>> URL: {VersionDetectionURL} <<<")
        print("------------------------------------------------")
        return
        
    print(f"--- Checking updates for {APP_NAME} ---")
    if not check_internet():
        print("- NO INTERNET CONNECTION. Skipping Update Checker.")
        OFFLINE_MODE = True # pyright: ignore[reportConstantRedefinition]
        return

    try:
        separator = "&" if "?" in VersionDetectionURL else "?"
        cache_buster = f"{VersionDetectionURL}{separator}t={int(time.time())}&nocache={random.randint(1, 9999)}"
        response = requests.get(cache_buster, timeout=10)
        
        if response.status_code == 200:
            try:
                data = response.json()
            except json.JSONDecodeError as e:
                preview = response.text.strip().replace("\r", " ").replace("\n", " ")[:300]
                print("- Update checker received invalid JSON. Skipping update check.")
                log_error(
                    "Update checker received invalid JSON from the version detection URL.\n"
                    f"URL: {VersionDetectionURL}\n"
                    f"JSON error: {e}\n"
                    f"Response preview: {preview}"
                )
                return

            if not isinstance(data, dict):
                print("- Update checker response was not a JSON object. Skipping update check.")
                log_error(
                    "Update checker response was not a JSON object.\n"
                    f"URL: {VersionDetectionURL}\n"
                    f"Response type: {type(data).__name__}"
                )
                return

            latest_version = None
            
            for vid in APP_IDS:
                if vid in data:
                    val = str(data[vid]).strip() # pyright: ignore[reportUnknownArgumentType]
                    
                    if val == "USE_GLOBAL":
                        latest_version = str(data.get("GLOBAL_LATEST")).strip() # pyright: ignore[reportUnknownMemberType, reportUnknownArgumentType]
                    else:
                        latest_version = val
                    
                    print(f"- Update Check Matched ID: {vid} (Version: {latest_version})")
                    break 

            if latest_version and latest_version != APP_VERSION:
                print(f"Update Found. Local: {APP_VERSION} | Cloud: {latest_version}")
                
                # --- Fetch download URL from GitHub API ---
                try:
                    gh_response = requests.get("https://api.github.com/repos/NewPythonX-NPX/VeloStrap/releases/latest", timeout=10)
                    latest_release = gh_response.json()  # The API returns a single release object, not a list

                    if latest_release.get("assets") and len(latest_release["assets"]) > 0:
                        download_url = latest_release["assets"][0]["browser_download_url"]
                    else:
                        download_url = latest_release.get("html_url") or "https://github.com/NewPythonX-NPX/VeloStrap/releases"

                    webbrowser.open(download_url)
                except Exception:
                    webbrowser.open("https://github.com/NewPythonX-NPX/VeloStrap/releases/latest")
                
                os._exit(0)

            else:
                print(f"Everything matches! Launching {APP_NAME}...")
        else:
            print(f"- Update checker returned {response.status_code}. Skipping update check.")
                
    except Exception as e:
        print(f"Update Checker Failed: {e}")
        log_error(str(e))
        
def get_json_object_file(file_path, label, default=None, allowed_keys=None): # pyright: ignore[reportMissingParameterType, reportUnknownParameterType]
    if default is None:
        default = {}
    if not os.path.exists(file_path): # pyright: ignore[reportUnknownArgumentType]
        return dict(default) # pyright: ignore[reportUnknownVariableType, reportUnknownArgumentType]

    try:
        with open(file_path, "r", encoding="utf-8") as file_handle: # pyright: ignore[reportUnknownArgumentType]
            payload = json.load(file_handle)
    except Exception as exc:
        log_error(f"{label} could not be read and will be ignored: {exc}")
        return dict(default) # pyright: ignore[reportUnknownVariableType, reportUnknownArgumentType]

    if not isinstance(payload, dict):
        log_error(f"{label} should contain a JSON object, got {type(payload).__name__}.")
        return dict(default) # pyright: ignore[reportUnknownVariableType, reportUnknownArgumentType]

    if allowed_keys is None:
        return payload # pyright: ignore[reportUnknownVariableType]

    filtered_payload = {}
    for key, value in payload.items(): # pyright: ignore[reportUnknownVariableType]
        if key in allowed_keys:
            filtered_payload[key] = value
        else:
            log_error(f"{label} ignored unknown field '{key}'.")
    return filtered_payload # pyright: ignore[reportUnknownVariableType]

def normalize_raw_github_url(url):
    cleaned_url = str(url).strip() # pyright: ignore[reportUnknownArgumentType]
    cleaned_url = cleaned_url.replace("raw.githuberusercontent.com", "raw.githubusercontent.com")
    cleaned_url = cleaned_url.replace("raw.githubuserconten.com", "raw.githubusercontent.com")
    cleaned_url = cleaned_url.replace("raw.githubusercontents.com", "raw.githubusercontent.com")
    if cleaned_url.startswith("http://raw.githubusercontent.com"):
        cleaned_url = "https://" + cleaned_url[len("http://"):]
    return cleaned_url

def get_legal_cache_path(document):
    return os.path.join(get_app_directory(), "IMPORTANT", "Cached", document["file_name"])

def get_legal_local_path(document):
    return resource_path(os.path.join("IMPORTANT", document["file_name"]))

def read_text_file(file_path):
    with open(file_path, "r", encoding="utf-8") as file_handle:
        return file_handle.read()

def write_text_file(file_path, text):
    os.makedirs(os.path.dirname(os.path.abspath(file_path)), exist_ok=True)
    with open(file_path, "w", encoding="utf-8") as file_handle:
        file_handle.write(text)

def fetch_remote_legal_text(document):
    remote_url = normalize_raw_github_url(document["remote_url"])
    response = requests.get(remote_url, timeout=10)
    response.raise_for_status()
    text = response.text
    if not text.strip():
        raise RuntimeError(f"{document['title']} remote document was empty.")
    return text

def load_legal_text(document):
    cache_path = get_legal_cache_path(document)
    local_path = get_legal_local_path(document)

    if check_internet():
        try:
            text = fetch_remote_legal_text(document)
            write_text_file(cache_path, text)
            return text, "remote"
        except Exception as exc:
            log_error(f"Could not refresh {document['title']} from remote; falling back to cache/local: {exc}")

    for fallback_path, source_name in ((cache_path, "cache"), (local_path, "local")):
        try:
            if os.path.exists(fallback_path):
                return read_text_file(fallback_path), source_name
        except Exception as exc:
            log_error(f"Could not read {document['title']} from {source_name}: {exc}")

    return (
        f"Could not load {document['title']} file.\n\n"
        f"By proceeding you agree to the {document['title']}.",
        "missing",
    )


def resolve_linked_legal_text(link_target):
    target = str(link_target).strip().strip("<>")
    if not target:
        return None

    # Remote markdown links should be embedded if available.
    if target.lower().startswith(("http://", "https://")):
        normalized_target = normalize_raw_github_url(target)
        if "/blob/" in normalized_target.lower():
            try:
                raw_target = normalized_target.replace("https://github.com/", "https://raw.githubusercontent.com/").replace("/blob/", "/")
                normalized_target = normalize_raw_github_url(raw_target)
            except Exception:
                pass

        if normalized_target.lower().endswith(".md") or ".md" in os.path.basename(normalized_target).lower():
            try:
                response = requests.get(normalized_target, timeout=10)
                response.raise_for_status()
                if response.text.strip():
                    return response.text
            except Exception as exc:
                log_error(f"Could not fetch linked remote legal markdown '{normalized_target}': {exc}")
                parsed = urlparse(normalized_target)
                file_name = unquote(os.path.basename(parsed.path))
                if file_name:
                    fallback_cached = os.path.join(get_app_directory(), "IMPORTANT", "Cached", file_name)
                    if os.path.exists(fallback_cached):
                        try:
                            return read_text_file(fallback_cached)
                        except Exception as inner_exc:
                            log_error(f"Could not read cached linked legal markdown '{fallback_cached}': {inner_exc}")
                    fallback_local = resource_path(os.path.join("IMPORTANT", file_name))
                    if os.path.exists(fallback_local):
                        try:
                            return read_text_file(fallback_local)
                        except Exception as inner_exc:
                            log_error(f"Could not read linked local legal markdown '{fallback_local}': {inner_exc}")
        return None

    # Local markdown documents inside IMPORTANT.
    local_target = resource_path(os.path.join("IMPORTANT", target.replace("/", os.sep)))
    if os.path.exists(local_target):
        try:
            return read_text_file(local_target)
        except Exception as exc:
            log_error(f"Could not read linked local legal markdown '{local_target}': {exc}")
            return None

    # Attempt to resolve by known legal document file names.
    for document in LEGAL_DOCUMENTS:
        if document["file_name"].lower() == os.path.basename(target).lower():
            try:
                linked_text, _ = load_legal_text(document)
                return linked_text
            except Exception as exc:
                log_error(f"Could not load linked legal document '{target}': {exc}")
                return None

    return None


def get_latest_version(data, id_list, global_key):
    for vid in id_list:
        if vid in data:
            val = str(data[vid]).strip()
            if val.startswith("USE_GLOBAL"):
                return str(data.get(global_key, "")).strip() or None
            return val or None
    return None

def set_latest_legal_version(document, version):
    globals()[document["latest_global"]] = version

def get_latest_legal_version(document, agreed_data):
    return (
        globals().get(document["latest_global"])
        or agreed_data.get(document["version_key"])
        or "local"
    )

def run_general_extra_check():
    global OFFLINE_MODE

    if DEVELOPER_MODE:
        print("- Developer Mode: Skipping extra legal/version checks.")
        developer_log("Developer mode skipped run_general_extra_check.")
        return

    print(f"--- Checking extra updates for {APP_NAME} ---")
    if not check_internet():
        print("- NO INTERNET CONNECTION. Skipping Extra Checker.")
        OFFLINE_MODE = True # pyright: ignore[reportConstantRedefinition]
        return

    # Load current agreed versions and flags
    agreement_file = os.path.join(get_app_directory(), "agreement.json")
    agreement_keys = {doc["agreed_key"] for doc in LEGAL_DOCUMENTS}.union({doc["version_key"] for doc in LEGAL_DOCUMENTS})
    agreed_data = get_json_object_file(agreement_file, "agreement.json", allowed_keys=agreement_keys)

    # Fetch remote data once
    try:
        separator = "&" if "?" in ExtraDetectionURL else "?"
        cache_buster = f"{ExtraDetectionURL}{separator}t={int(time.time())}&nocache={random.randint(1, 9999)}"
        response = requests.get(cache_buster, timeout=10)
        response.raise_for_status()
        try:
            data = response.json()
        except json.JSONDecodeError as e:
            preview = response.text.strip()[:300]
            print("- Extra Checker received invalid JSON. Skipping update check.")
            log_error(f"Extra Checker JSON error: {e}\nURL: {ExtraDetectionURL}\nPreview: {preview}")
            return
        if not isinstance(data, dict):
            print("- Extra Checker response was not a JSON object. Skipping update check.")
            log_error(f"Extra Checker response type: {type(data).__name__}")
            return
    except Exception as e:
        print(f"Failed to fetch extra updates: {e}")
        log_error(str(e))
        return

    agreement_changed = False
    for document in LEGAL_DOCUMENTS:
        remote_version = get_latest_version(data, document["ids"], document["global_key"])
        set_latest_legal_version(document, remote_version)

        if remote_version:
            stored_version = agreed_data.get(document["version_key"])
            if not stored_version or remote_version != stored_version:
                print(f"- New {document['title']} version detected: {remote_version} (was {stored_version})")
                agreed_data[document["agreed_key"]] = False
                agreement_changed = True
            else:
                print(f"- {document['title']} up-to-date.")
        else:
            print(f"- No valid {document['title']} version found in remote data.")

        try:
            _, source_name = load_legal_text(document)
            print(f"- {document['title']} legal text ready from {source_name}.")
        except Exception as exc:
            log_error(f"Could not prepare {document['title']} legal text: {exc}")

    if agreement_changed:
        with open(agreement_file, "w", encoding="utf-8") as f:
            json.dump(agreed_data, f, indent=4)
    
