def pump_tk_widget(widget): # pyright: ignore[reportMissingParameterType, reportUnknownParameterType]
    try:
        if widget is not None and widget.winfo_exists(): # pyright: ignore[reportUnknownMemberType]
            widget.update_idletasks() # pyright: ignore[reportUnknownMemberType]
            widget.update() # pyright: ignore[reportUnknownMemberType]
    except tkinter.TclError:
        pass

def prepare_linux_modal_parent(parent): # pyright: ignore[reportMissingParameterType, reportUnknownParameterType]
    if parent is None or sys.platform != "linux_arch":
        return
    try:
        if parent.winfo_exists(): # pyright: ignore[reportUnknownMemberType]
            parent.deiconify()
            parent.lift()
            pump_tk_widget(parent)
    except tkinter.TclError:
        pass

def wait_modal_dialog(dialog, parent=None): # pyright: ignore[reportMissingParameterType, reportUnknownParameterType]
    if sys.platform != "linux_arch":
        dialog.wait_window() # pyright: ignore[reportUnknownMemberType]
        return
    while dialog.winfo_exists():
        pump_tk_widget(dialog)
        pump_tk_widget(parent)

def destroy_modal_dialog(dialog, parent=None): # pyright: ignore[reportMissingParameterType, reportUnknownParameterType]
    try:
        if dialog.winfo_exists(): # pyright: ignore[reportUnknownMemberType]
            dialog.grab_release() # pyright: ignore[reportUnknownMemberType]
    except tkinter.TclError:
        pass
    try:
        if dialog.winfo_exists(): # pyright: ignore[reportUnknownMemberType]
            dialog.destroy() # pyright: ignore[reportUnknownMemberType]
    except tkinter.TclError:
        pass
    if sys.platform == "linux_arch":
        pump_tk_widget(parent)

def safe_modal_grab(window, parent=None): # pyright: ignore[reportMissingParameterType, reportUnknownParameterType]
    if sys.platform != "linux_arch":
        window.grab_set() # pyright: ignore[reportUnknownMemberType]
        return

    prepare_linux_modal_parent(parent)
    pump_tk_widget(window)
    try:
        window.deiconify()
        window.lift()
        window.focus_force()
    except tkinter.TclError:
        pass

def present_modal_toplevel(window, parent=None): # pyright: ignore[reportMissingParameterType, reportUnknownParameterType]
    if parent is not None:
        try:
            window.transient(parent) # pyright: ignore[reportUnknownMemberType]
        except tkinter.TclError:
            pass

    prepare_linux_modal_parent(parent)
    pump_tk_widget(window) # pyright: ignore[reportUnknownArgumentType]

    try:
        window.deiconify() # pyright: ignore[reportUnknownMemberType]
        window.lift() # pyright: ignore[reportUnknownMemberType]
        if sys.platform == "linux_arch":
            window.attributes("-topmost", True)
            window.update_idletasks()
            window.attributes("-topmost", False)
        window.focus_force() # pyright: ignore[reportUnknownMemberType]
    except tkinter.TclError:
        pass

    safe_modal_grab(window, parent) # pyright: ignore[reportUnknownArgumentType]

def agreement(parent): # pyright: ignore[reportMissingParameterType, reportUnknownParameterType]
    """
    Shows Legal Disclaimers.
    Returns True only if all are agreed, False otherwise.
    Agreement status and accepted versions are stored in agreement.json.
    """
    script_dir = get_app_directory()
    agreement_file = os.path.join(script_dir, "agreement.json")

    # --- Load current agreement status ---
    agreement_keys = {doc["agreed_key"] for doc in LEGAL_DOCUMENTS}.union({doc["version_key"] for doc in LEGAL_DOCUMENTS})
    already_agreed = get_json_object_file(agreement_file, "agreement.json", allowed_keys=agreement_keys)

    if all(already_agreed.get(document["agreed_key"]) for document in LEGAL_DOCUMENTS):
        return True

    def open_link(link_target):
        target = str(link_target).strip()
        if not target:
            return
        if target.lower().startswith(("http://", "https://")):
            webbrowser.open(target)
            return
        local_target = resource_path(os.path.join("IMPORTANT", target.replace("/", os.sep)))
        if os.path.exists(local_target):
            webbrowser.open(local_target)
            return

        local_target = resource_path(os.path.join("IMPORTANT", target.replace("/", os.sep)))
        if os.path.exists(local_target):
            webbrowser.open(local_target)
        else:
            webbrowser.open(target)

    def insert_linked_markdown(textbox, text):
        link_pattern = re.compile(r"\[([^\]]+)\]\(([^)]+)\)|(https?://[^\s)]+)|\[([^\]]+\.md)\]")
        position = 0
        link_index = 0

        for match in link_pattern.finditer(text):
            textbox.insert("end", text[position:match.start()])

            if match.group(1) and match.group(2):
                display_text = match.group(1)
                link_target = match.group(2)
            elif match.group(3):
                display_text = match.group(3)
                link_target = match.group(3)
            else:
                display_text = match.group(4)
                link_target = match.group(4)

            embedded_text = resolve_linked_legal_text(link_target)
            if embedded_text is not None:
                insert_linked_markdown(textbox, embedded_text)
            else:
                tag_name = f"legal_link_{link_index}"
                textbox.insert("end", display_text, tag_name)
                try:
                    textbox.tag_config(tag_name, foreground="#3B82F6", underline=True)
                    textbox.tag_bind(tag_name, "<Button-1>", lambda _event, target=link_target: open_link(target))
                    textbox.tag_bind(tag_name, "<Enter>", lambda _event: textbox.configure(cursor="hand2"))
                    textbox.tag_bind(tag_name, "<Leave>", lambda _event: textbox.configure(cursor=""))
                except Exception as exc:
                    log_error(f"Could not format agreement link '{display_text}': {exc}")
                link_index += 1

            position = match.end()

        textbox.insert("end", text[position:])

    # --- Helper to show a modal with markdown content ---
    def show_agreement_dialog(document): # pyright: ignore[reportUnknownParameterType, reportMissingParameterType]
        title = document["title"]
        text, source_name = load_legal_text(document)
        developer_log(f"Showing {title} agreement text from {source_name}.")
        prepare_linux_modal_parent(parent) # pyright: ignore[reportUnknownArgumentType]

        dialog = ctk.CTkToplevel(parent) # pyright: ignore[reportUnknownArgumentType]
        dialog.title(title) # pyright: ignore[reportUnknownArgumentType]
        dialog.geometry("600x500")
        dialog.resizable(False, False)
        dialog.transient(parent) # pyright: ignore[reportUnknownArgumentType]
        dialog.protocol("WM_DELETE_WINDOW", lambda: None)  # block close

        header = ctk.CTkLabel(dialog, text=title, font=("Arial", 16, "bold")) # pyright: ignore[reportUnknownArgumentType]
        header.pack(pady=(15, 5)) # pyright: ignore[reportUnknownMemberType]

        textbox = ctk.CTkTextbox(dialog, wrap="word", height=250)
        insert_linked_markdown(textbox, text)
        textbox.configure(state="disabled")  # pyright: ignore[reportUnknownMemberType] # read-only
        textbox.pack(pady=5, padx=20, fill="both", expand=True) # pyright: ignore[reportUnknownMemberType]

        agree_var = ctk.BooleanVar(value=False)
        checkbox = ctk.CTkCheckBox(dialog, text=document["check_text"], variable=agree_var,
                                   onvalue=True, offvalue=False)
        checkbox.pack(pady=(10, 5)) # pyright: ignore[reportUnknownMemberType]

        button_frame = ctk.CTkFrame(dialog, fg_color="transparent")
        button_frame.pack(pady=15) # pyright: ignore[reportUnknownMemberType]

        result_flag = False

        def on_agree():
            nonlocal result_flag
            result_flag = True
            destroy_modal_dialog(dialog, parent) # pyright: ignore[reportUnknownArgumentType]

        def on_decline():
            nonlocal result_flag
            result_flag = False
            destroy_modal_dialog(dialog, parent) # pyright: ignore[reportUnknownArgumentType]

        agree_btn = ctk.CTkButton(button_frame, text="I Agree", command=on_agree,
                                  state="disabled", font=("Arial", 14))
        agree_btn.pack(side="left", padx=10) # pyright: ignore[reportUnknownMemberType]

        decline_btn = ctk.CTkButton(button_frame, text="Decline", command=on_decline,
                                    fg_color="gray", hover_color="darkred", font=("Arial", 14))
        decline_btn.pack(side="left", padx=10) # pyright: ignore[reportUnknownMemberType]

        def toggle_agree(*args): # pyright: ignore[reportUnknownParameterType, reportMissingParameterType]
            agree_btn.configure(state="normal" if agree_var.get() else "disabled") # pyright: ignore[reportUnknownMemberType]
        agree_var.trace_add("write", toggle_agree) # pyright: ignore[reportUnknownArgumentType]

        safe_modal_grab(dialog, parent) # pyright: ignore[reportUnknownArgumentType]
        wait_modal_dialog(dialog, parent) # pyright: ignore[reportUnknownArgumentType]
        return result_flag

    for document in LEGAL_DOCUMENTS:
        if already_agreed.get(document["agreed_key"]): # pyright: ignore[reportUnknownMemberType]
            continue

        if not show_agreement_dialog(document):
            return False

        already_agreed[document["agreed_key"]] = True
        already_agreed[document["version_key"]] = get_latest_legal_version(document, already_agreed)
        with open(agreement_file, "w", encoding="utf-8") as f:
            json.dump(already_agreed, f, indent=4)
            
    return True
        
