    def handle_fastflag_control_change(self, _=None):
        if getattr(self, "syncing_fastflag_controls", False):
            self.refresh_fastflag_views(use_current_ui=True)
            return
        if not self.check_rate_limit(): return
        self.refresh_fastflag_views(use_current_ui=True)

    def prompt_fastflag_overwrite(self, conflicts, parent=None):
        dialog_parent = parent or self
        overwrite_dialog = ctk.CTkToplevel(self)
        overwrite_dialog.title("Overwrite FastFlags?")
        overwrite_dialog.geometry("560x360")
        overwrite_dialog.resizable(False, False)
        overwrite_dialog.configure(fg_color=self.get_window_bg_color())

        result = {"overwrite": False}

        ctk.CTkLabel(
            overwrite_dialog,
            text="Do you want to overwrite these fastflag(s)?",
            font=ctk.CTkFont(size=18, weight="bold"),
            text_color=self.get_primary_text_color(),
            wraplength=self.get_dialog_wraplength(),
            justify="left"
        ).pack(anchor="w", padx=20, pady=(18, 8))

        comparison_box = ctk.CTkTextbox(overwrite_dialog, width=500, height=220)
        comparison_box.pack(fill="both", expand=True, padx=20, pady=(0, 12))

        comparison_lines = []
        for flag_name, values in sorted(conflicts.items(), key=lambda item: item[0].lower()):
            comparison_lines.append(
                f"{flag_name}\n"
                f"Existing Flag: {self.format_fastflag_value(values['existing'])}\n"
                f"New Flag: {self.format_fastflag_value(values['new'])}\n"
            )

        comparison_box.insert("1.0", "\n".join(comparison_lines).strip())
        comparison_box.configure(state="disabled")

        button_row = ctk.CTkFrame(overwrite_dialog, fg_color="transparent")
        button_row.pack(fill="x", padx=20, pady=(0, 18))

        def save_and_close():
            result["overwrite"] = True
            destroy_modal_dialog(overwrite_dialog, dialog_parent)

        def decline_overwrite():
            destroy_modal_dialog(overwrite_dialog, dialog_parent)

        ctk.CTkButton(button_row, text="Save", width=120, command=save_and_close).pack(side="right", padx=(8, 0))
        ctk.CTkButton(
            button_row,
            text="No",
            width=120,
            **self.get_neutral_button_style(),
            command=decline_overwrite
        ).pack(side="right")

        self.center_toplevel_window(overwrite_dialog, width=560, height=360)
        present_modal_toplevel(overwrite_dialog, dialog_parent)
        wait_modal_dialog(overwrite_dialog, dialog_parent)
        return result["overwrite"]

    def open_fastflag_editor(self):
        if self.fastflag_editor_window and self.fastflag_editor_window.winfo_exists():
            self.fastflag_editor_window.focus()
            return

        # Modern, smaller, semi-transparent grey layout
        self.fastflag_editor_window = ctk.CTkToplevel(self)
        self.fastflag_editor_window.title("FastFlag Editor")
        self.fastflag_editor_window.geometry("540x650")
        self.fastflag_editor_window.resizable(False, False)
        # Deep grey/transparent look
        self.fastflag_editor_window.configure(fg_color="#18181B" if self.get_current_theme() in ["Dark"] else "#E4E4E7")

        # Ensure Custom-Flags folder exists only when editor is opened
        os.makedirs(self.custom_flags_path, exist_ok=True)

        def close_editor():
            if self.fastflag_editor_window and self.fastflag_editor_window.winfo_exists():
                self.fastflag_editor_window.destroy()
            self.fastflag_editor_window = None

        self.fastflag_editor_window.protocol("WM_DELETE_WINDOW", close_editor)

        container = ctk.CTkScrollableFrame(self.fastflag_editor_window, fg_color="transparent")
        container.pack(fill="both", expand=True, padx=15, pady=15)

        # Track dirty/unsaved JSON edits inside the editor
        self.fastflag_editor_dirty = False

        # === TABVIEW LAYOUT ===
        tabview = ctk.CTkTabview(container, width=520)
        tabview.pack(fill="both", expand=False)
        tabview.add("ADD SINGLE")
        tabview.add("JSON")
        tabview.add("SHORTCUTS")
        tabview.add("MISC")

        # === ADD SINGLE TAB ===
        single_container = tabview.tab("ADD SINGLE")
        ctk.CTkLabel(single_container, text="Add Single FastFlag", font=ctk.CTkFont(size=16, weight="bold")).pack(anchor="w", pady=(8, 10))
        single_frame = ctk.CTkFrame(single_container, fg_color=self.get_surface_bg_color(), corner_radius=8)
        single_frame.pack(fill="x", pady=(0, 12), ipady=8)

        ctk.CTkLabel(single_frame, text="Key:").grid(row=0, column=0, padx=10, pady=(10, 5), sticky="w")
        self.single_key_entry = ctk.CTkEntry(single_frame, width=360, placeholder_text="e.g. FFlagHandleAltEnterFullscreenManually")
        self.single_key_entry.grid(row=0, column=1, padx=10, pady=(10, 5))

        ctk.CTkLabel(single_frame, text="Value:").grid(row=1, column=0, padx=10, pady=(0, 10), sticky="w")
        self.single_val_entry = ctk.CTkEntry(single_frame, width=360, placeholder_text="e.g. False")
        self.single_val_entry.grid(row=1, column=1, padx=10, pady=(0, 10))

        def add_single_flag():
            if not self.check_rate_limit():
                return
            k = self.single_key_entry.get().strip()
            v = self.single_val_entry.get().strip()
            if not k or not v:
                return

            # Basic type conversion
            if isinstance(v, str):
                if v.lower() == "true":
                    v = True
                elif v.lower() == "false":
                    v = False
                else:
                    # try int or float
                    try:
                        if "." in v:
                            v = float(v)
                        else:
                            v = int(v)
                    except Exception:
                        pass

            try:
                imported_flags, _ = self.parse_fastflag_payload(json.dumps({k: v}), parent=self.fastflag_editor_window)
                self.apply_imported_fastflags(imported_flags, parent=self.fastflag_editor_window)
                self.single_key_entry.delete(0, "end")
                self.single_val_entry.delete(0, "end")
            except Exception as e:
                messagebox.showerror("Error", str(e), parent=self.fastflag_editor_window)

        ctk.CTkButton(single_frame, text="Add", command=add_single_flag, width=120).grid(row=2, column=1, sticky="e", padx=10, pady=(6,10))

        # === JSON TAB ===
        json_container = tabview.tab("JSON")
        ctk.CTkLabel(json_container, text="Add JSON", font=ctk.CTkFont(size=16, weight="bold")).pack(anchor="w", pady=(8, 10))

        json_frame = ctk.CTkFrame(json_container, fg_color=self.get_surface_bg_color(), corner_radius=8)
        json_frame.pack(fill="x", pady=(0, 12), ipady=6)

        self.fastflag_json_box = ctk.CTkTextbox(json_frame, width=480, height=220, wrap="word", fg_color=self.get_secondary_bg_color())
        self.fastflag_json_box.pack(padx=10, pady=(10, 8))

        # Track modifications in the textbox to mark editor dirty
        def _on_json_modified(event=None):
            try:
                # The underlying Text widget exposes edit_modified
                widget = self.fastflag_json_box._text
                if widget.edit_modified():
                    self.fastflag_editor_dirty = True
                    widget.edit_modified(False)
            except Exception:
                # Fallback: always mark dirty on any event
                self.fastflag_editor_dirty = True

        try:
            # Try to bind the virtual modified event
            self.fastflag_json_box._text.bind("<<Modified>>", _on_json_modified)
        except Exception:
            # Best-effort: bind key events
            self.fastflag_json_box.bind("<Key>", lambda e: setattr(self, 'fastflag_editor_dirty', True))

        btn_row = ctk.CTkFrame(json_frame, fg_color="transparent")
        btn_row.pack(fill="x", padx=10, pady=(0, 8))

        ctk.CTkButton(btn_row, text="Add JSON file", command=self.import_fastflags_from_file, width=120).pack(side="left")
        ctk.CTkButton(btn_row, text="Save", command=self.save_fastflags_from_json_box, width=120).pack(side="right")

        # === SHORTCUTS TAB ===
        shortcuts_container = tabview.tab("SHORTCUTS")
        ctk.CTkLabel(shortcuts_container, text="Shortcuts (editor only)", font=ctk.CTkFont(size=14, weight="bold")).pack(anchor="w", pady=(8, 8))
        ctk.CTkLabel(shortcuts_container, text="These are shortcuts only for the fastflag editor", text_color=self.get_muted_text_color()).pack(anchor="w", pady=(2,4))
        ctk.CTkLabel(shortcuts_container, text="Ctrl+S = Save changes", text_color=self.get_muted_text_color()).pack(anchor="w", pady=(2,2))
        ctk.CTkLabel(shortcuts_container, text="Ctrl+W = Clear changes", text_color=self.get_muted_text_color()).pack(anchor="w", pady=(2,2))

        # === MISC TAB ===
        misc_container = tabview.tab("MISC")
        ctk.CTkLabel(misc_container, text="Miscellaneous", font=ctk.CTkFont(size=14, weight="bold")).pack(anchor="w", pady=(8, 8))

        def clear_all_custom_flags():
            if not self.custom_fast_flags:
                messagebox.showinfo("Clear Custom FastFlags", "There are no custom fastflags to clear.", parent=self.fastflag_editor_window)
                return
            keys = sorted(self.custom_fast_flags.keys(), key=lambda k: k.lower())
            summary = "The following custom fastflags will be removed:\n\n" + "\n".join(keys)
            confirm = messagebox.askyesno("Confirm Clear All", f"Are you sure you want to clear all custom FastFlags?\n\n{len(keys)} flags will be removed.", parent=self.fastflag_editor_window)
            if not confirm:
                return
            # Show expected changes
            messagebox.showinfo("Clearing FastFlags", summary, parent=self.fastflag_editor_window)
            self.persist_custom_fast_flags({}, sync_launcher=True, refresh_views=True)

        def copy_custom_fastflags_json():
            try:
                json_text = json.dumps(self.custom_fast_flags, indent=4, ensure_ascii=False)
                self.fastflag_editor_window.clipboard_clear()
                self.fastflag_editor_window.clipboard_append(json_text)
                messagebox.showinfo("Copied", "Custom FastFlags JSON copied to clipboard.", parent=self.fastflag_editor_window)
            except Exception as exc:
                messagebox.showerror("Error", f"Could not copy to clipboard: {exc}", parent=self.fastflag_editor_window)

        ctk.CTkButton(misc_container, text="Clear all custom fastflags", fg_color="#B91C1C", hover_color="#991B1B", command=clear_all_custom_flags).pack(anchor="w", pady=(6,8), padx=6)
        self.misc_custom_count_label = ctk.CTkLabel(misc_container, text=f"Custom fastflags: {len(self.custom_fast_flags)}")
        self.misc_custom_count_label.pack(anchor="w", pady=(2,8), padx=6)
        ctk.CTkButton(misc_container, text="Copy custom fastflags json to clipboard", command=copy_custom_fastflags_json).pack(anchor="w", pady=(2,8), padx=6)

        # === SAVED FLAGS LIST (kept below tabs) ===
        ctk.CTkLabel(container, text="Saved Custom FastFlags", font=ctk.CTkFont(size=14, weight="bold")).pack(anchor="w", pady=(10, 6))
        self.custom_flags_list_frame = ctk.CTkScrollableFrame(container, width=520, height=180, fg_color=self.get_surface_bg_color())
        self.custom_flags_list_frame.pack(fill="x")

        self.refresh_fastflag_views(use_current_ui=True, force=True)
        self.refresh_custom_fastflag_list(force=True)

        # Keyboard shortcuts for editor
        def _save_shortcut(event=None):
            # Prefer saving JSON box if it has content, else show info
            try:
                raw_text = self.fastflag_json_box.get("1.0", "end").strip()
                if raw_text:
                    self.save_fastflags_from_json_box()
                else:
                    # nothing in JSON box; just refresh views
                    self.refresh_fastflag_views(use_current_ui=True)
                return "break"
            except Exception:
                return None

        def _clear_shortcut(event=None):
            # Clear JSON box edits
            try:
                self.fastflag_json_box.delete("1.0", "end")
                self.fastflag_editor_dirty = False
                return "break"
            except Exception:
                return None

        try:
            self.fastflag_editor_window.bind_all("<Control-s>", lambda e: _save_shortcut(e))
            self.fastflag_editor_window.bind_all("<Control-S>", lambda e: _save_shortcut(e))
            self.fastflag_editor_window.bind_all("<Control-w>", lambda e: _clear_shortcut(e))
            self.fastflag_editor_window.bind_all("<Control-W>", lambda e: _clear_shortcut(e))
        except Exception:
            pass

        # Override close to warn about unsaved JSON edits
        def close_editor():
            if getattr(self, 'fastflag_editor_dirty', False):
                should_save = messagebox.askyesno("You have unsaved changes. Wanna save them? 😁", "Save changes before closing?", parent=self.fastflag_editor_window)
                if should_save:
                    raw_text = self.fastflag_json_box.get("1.0", "end").strip()
                    try:
                        imported_flags, fixed_text = self.parse_fastflag_payload(raw_text, source_label="FastFlag JSON", parent=self.fastflag_editor_window)
                        # Build a change list for display
                        diffs = []
                        current = dict(self.custom_fast_flags)
                        for k, v in imported_flags.items():
                            old = current.get(k, "<not set>")
                            if old != v:
                                diffs.append(f"{k} -> {v} (was: {old})")
                        if diffs:
                            messagebox.showinfo("Changes to be saved:", "\n".join(diffs), parent=self.fastflag_editor_window)
                        self.apply_imported_fastflags(imported_flags, parent=self.fastflag_editor_window)
                        self.fastflag_editor_dirty = False
                    except FastFlagImportValidationError as exc:
                        self.handle_partial_fastflag_import(exc, parent=self.fastflag_editor_window)
                    except Exception as exc:
                        self.handle_critical_fastflag_error("Could not save FastFlags before closing.", exc, parent=self.fastflag_editor_window)
                        return
                # If user chose not to save, just close
            if self.fastflag_editor_window and self.fastflag_editor_window.winfo_exists():
                self.fastflag_editor_window.destroy()
            self.fastflag_editor_window = None

        self.fastflag_editor_window.protocol("WM_DELETE_WINDOW", close_editor)

        self.center_toplevel_window(self.fastflag_editor_window, width=540, height=650)
        present_modal_toplevel(self.fastflag_editor_window, self)

    def handle_partial_fastflag_import(self, validation_error, parent=None):
        parent_window = parent or self
        merged_custom_flags = self.merge_fastflags_with_existing(validation_error.valid_flags, parent=parent_window)
        self.persist_custom_fast_flags(merged_custom_flags)

        saved_count = sum(
            1 for key, value in validation_error.valid_flags.items()
            if self.custom_fast_flags.get(key) == value
        )
        total_fastflags = len(self.build_fast_flags(use_current_ui=True))

        messagebox.showinfo(
            "FastFlag Cleanup",
            f"Saved {saved_count} Fastflags and removed {validation_error.removed_count} Fastflags, total fastflags {total_fastflags}",
            parent=parent_window
        )

        self.handle_critical_fastflag_error(
            "Some FastFlag entries were missing a key or value and had to be removed.",
            validation_error,
            parent=parent_window
        )

    def apply_imported_fastflags(self, imported_flags, parent=None):
        parent_window = parent or self
        merged_custom_flags = self.merge_fastflags_with_existing(imported_flags, parent=parent_window)
        self.persist_custom_fast_flags(merged_custom_flags)

        saved_count = sum(
            1 for key, value in imported_flags.items()
            if self.custom_fast_flags.get(key) == value
        )
        total_fastflags = len(self.build_fast_flags(use_current_ui=True))

        messagebox.showinfo(
            "FastFlags Saved",
            f"Saved {saved_count} Fastflags. Total fastflags {total_fastflags}",
            parent=parent_window
        )

    def import_fastflags_from_file(self):
        selected_file = filedialog.askopenfilename(
            title="Select a FastFlag JSON file",
            filetypes=[("JSON files", "*.json"), ("All files", "*.*")]
        )
        if not selected_file:
            return

        try:
            with open(selected_file, "r", encoding="utf-8") as file_handle:
                raw_text = file_handle.read()
        except Exception as exc:
            self.handle_critical_fastflag_error(
                f"VeloStrap could not read '{os.path.basename(selected_file)}'.",
                exc,
                parent=self.fastflag_editor_window or self
            )

        try:
            imported_flags, _ = self.parse_fastflag_payload(
                raw_text,
                source_label=os.path.basename(selected_file),
                parent=self.fastflag_editor_window
            )
            self.apply_imported_fastflags(imported_flags, parent=self.fastflag_editor_window)
        except FastFlagImportValidationError as exc:
            self.handle_partial_fastflag_import(exc, parent=self.fastflag_editor_window)
        except Exception as exc:
            self.handle_critical_fastflag_error(
                f"{os.path.basename(selected_file)} could not be imported safely.",
                exc,
                parent=self.fastflag_editor_window or self
            )

    def save_fastflags_from_json_box(self):
        if not self.fastflag_json_box or not self.fastflag_json_box.winfo_exists():
            return

        raw_text = self.fastflag_json_box.get("1.0", "end").strip()
        if not raw_text:
            messagebox.showerror("FastFlag JSON", "Paste some FastFlag JSON before saving.", parent=self.fastflag_editor_window or self)
            return

        try:
            imported_flags, fixed_text = self.parse_fastflag_payload(
                raw_text,
                source_label="FastFlag JSON",
                parent=self.fastflag_editor_window
            )
            self.apply_imported_fastflags(imported_flags, parent=self.fastflag_editor_window)
            self.fastflag_json_box.delete("1.0", "end")
            self.fastflag_json_box.insert("1.0", fixed_text)
        except FastFlagImportValidationError as exc:
            self.handle_partial_fastflag_import(exc, parent=self.fastflag_editor_window)
        except Exception as exc:
            self.handle_critical_fastflag_error(
                "The FastFlag JSON box could not be imported safely.",
                exc,
                parent=self.fastflag_editor_window or self
            )

    def delete_custom_fastflag(self, flag_name):
        if flag_name not in self.custom_fast_flags:
            return

        if not messagebox.askyesno(
            "Delete FastFlag",
            f"Delete '{flag_name}' from CustomFFs.json?",
            parent=self.fastflag_editor_window or self
        ):
            return

        updated_custom_flags = dict(self.custom_fast_flags)
        del updated_custom_flags[flag_name]
        self.persist_custom_fast_flags(updated_custom_flags)

