    def position_ai_popup_window(self):
        if not (self.ai_popup_window and self.ai_popup_window.winfo_exists()):
            return

        width = 540
        height = 470
        try:
            self.ai_popup_window.update_idletasks()
            screen_width = self.ai_popup_window.winfo_screenwidth()
            screen_height = self.ai_popup_window.winfo_screenheight()
            y = max((screen_height - height) // 8, 50)
            if self.ai_popup_side == "left":
                x = 10
            else:
                x = max(screen_width - width - 10, 10)
            self.ai_popup_window.geometry(f"{width}x{height}+{x}+{y}")
        except Exception:
            pass

