    # ==========================================
    # ROBLOX VERSION / INSTALL MANAGEMENT
    # ==========================================
    def ensure_local_versions_root(self):
        os.makedirs(self.local_versions_path, exist_ok=True)
        return self.local_versions_path

    def get_hidden_process_kwargs(self):
        if os.name != "nt":
            return {}

        startupinfo = subprocess.STARTUPINFO()
        startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
        startupinfo.wShowWindow = 0

        hidden_kwargs = {"startupinfo": startupinfo}
        create_no_window = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        if create_no_window:
            hidden_kwargs["creationflags"] = create_no_window

        return hidden_kwargs

    def find_installed_roblox_folder(self, version_id):
        if not version_id:
            return None

        version_id = str(version_id).strip() # pyright: ignore[reportUnknownArgumentType]
        exact_folder = os.path.join(self.roblox_versions_path, version_id)
        exact_exe = os.path.join(exact_folder, "RobloxPlayerBeta.exe")
        if os.path.exists(exact_exe):
            return exact_folder

        return None

    def get_version_folder_sort_key(self, folder_path):
        # VeloStrap writes FastFlags and mod files into Roblox version folders, so
        # modification time can make an older install look newer than the real one.
        creation_times = []
        modification_times = []

        for candidate_path in [folder_path, os.path.join(folder_path, "RobloxPlayerBeta.exe")]:
            if not os.path.exists(candidate_path):
                continue

            try:
                creation_times.append(os.path.getctime(candidate_path))
            except OSError:
                pass

            try:
                modification_times.append(os.path.getmtime(candidate_path))
            except OSError:
                pass

        latest_creation_time = max(creation_times) if creation_times else 0
        latest_modification_time = max(modification_times) if modification_times else 0
        return (latest_creation_time, latest_modification_time, folder_path.lower())

    def get_version_folders(self, root_path):
        if not os.path.exists(root_path):
            return []

        folders = [os.path.join(root_path, folder_name) for folder_name in os.listdir(root_path) if os.path.isdir(os.path.join(root_path, folder_name))] # pyright: ignore[reportUnknownVariableType, reportUnknownArgumentType]
        folders.sort(key=self.get_version_folder_sort_key, reverse=True) # pyright: ignore[reportUnknownMemberType]
        return folders

    def get_installed_roblox_folder(self, expected_version=None):
        if expected_version:
            exact_folder = self.find_installed_roblox_folder(expected_version) # pyright: ignore[reportUnknownMemberType]
            if exact_folder:
                return exact_folder

        for folder in self.get_version_folders(self.roblox_versions_path): # pyright: ignore[reportUnknownVariableType, reportUnknownMemberType]
            exe_path = os.path.join(folder, "RobloxPlayerBeta.exe")
            if os.path.exists(exe_path):
                return folder

        return None

    def get_current_installed_roblox_folder(self):
        if self.last_known_live_version:
            exact_folder = self.find_installed_roblox_folder(self.last_known_live_version) # pyright: ignore[reportUnknownMemberType]
            if exact_folder:
                return exact_folder

        return self.get_installed_roblox_folder() # pyright: ignore[reportUnknownVariableType, reportUnknownMemberType]

    def get_live_roblox_version(self):
        response = requests.get(ROBLOX_LIVE_VERSION_API, timeout=15)
        response.raise_for_status()
        payload = response.json()

        version_id = payload.get("clientVersionUpload") or payload.get("version")
        if not version_id:
            raise RuntimeError("Roblox did not return a usable live version id.")

        self.last_known_live_version = str(version_id).strip()
        return self.last_known_live_version

    def cleanup_cached_versions(self, keep_version):
        root_path = os.path.abspath(self.ensure_local_versions_root())
        keep_path = os.path.abspath(os.path.join(root_path, keep_version))

        for entry in os.listdir(root_path):
            full_path = os.path.abspath(os.path.join(root_path, entry))
            if full_path == keep_path:
                continue

            if os.path.isdir(full_path) and os.path.commonpath([root_path, full_path]) == root_path:
                try:
                    shutil.rmtree(full_path)
                    print(f"- Removed old cached Roblox version folder: {full_path}")
                except Exception as e:
                    print(f"- Could not remove old cached version folder {full_path}: {e}")

    def download_roblox_installer(self, version_id, status_callback=None):
        cache_root = self.ensure_local_versions_root()
        version_cache_folder = os.path.join(cache_root, version_id)
        os.makedirs(version_cache_folder, exist_ok=True)

        download_candidates = [
            (f"https://setup.rbxcdn.com/{version_id}-RobloxPlayerInstaller.exe", "RobloxPlayerInstaller.exe"),
            (f"https://setup.rbxcdn.com/{version_id}-Roblox.exe", "Roblox.exe"),
            ("https://setup.rbxcdn.com/RobloxPlayerLauncher.exe", "RobloxPlayerLauncher.exe")
        ]

        for url, filename in download_candidates:
            destination = os.path.join(version_cache_folder, filename)
            if os.path.exists(destination) and os.path.getsize(destination) > 0:
                if status_callback:
                    status_callback("Downloading Roblox", "Using the cached Roblox installer...", "indeterminate")
                print(f"- Reusing cached installer: {destination}")
                self.cleanup_cached_versions(version_id) # pyright: ignore[reportUnknownMemberType]
                return destination

            try:
                if status_callback:
                    status_callback("Downloading Roblox", "Downloading the latest Roblox build...", "indeterminate")
                print(f"- Downloading Roblox from {url}")
                with requests.get(url, stream=True, timeout=(15, 60)) as response:
                    if response.status_code != 200:
                        print(f"- Download candidate skipped ({response.status_code}): {url}")
                        continue

                    total_bytes = int(response.headers.get("content-length", "0") or 0)
                    downloaded_bytes = 0
                    with open(destination, "wb") as file_handle:
                        for chunk in response.iter_content(chunk_size=DOWNLOAD_CHUNK_SIZE):
                            if chunk:
                                file_handle.write(chunk)
                                downloaded_bytes += len(chunk)
                                if status_callback:
                                    if total_bytes > 0:
                                        progress_value = min(downloaded_bytes / total_bytes, 1.0)
                                        status_callback(
                                            "Downloading Roblox latest build",
                                            f"Downloading Roblox.. {progress_value:.0%}",
                                            "determinate",
                                            progress_value
                                        )
                                    else:
                                        status_callback("Downloading Roblox", "Downloading the latest Roblox build...", "indeterminate")

                if os.path.exists(destination) and os.path.getsize(destination) > 0:
                    print(f"- SUCCESS: Roblox installer cached at {destination}")
                    self.cleanup_cached_versions(version_id) # pyright: ignore[reportUnknownMemberType]
                    return destination
            except Exception as e:
                print(f"- Roblox download candidate failed: {e}")
                if os.path.exists(destination):
                    try:
                        os.remove(destination)
                    except OSError:
                        pass

        raise RuntimeError("Could not download a Roblox installer from Roblox's CDN.")

    def wait_for_roblox_install(self, expected_version, status_callback=None):
        deadline = time.time() + INSTALL_WAIT_SECONDS
        while time.time() < deadline:
            installed_folder = self.get_installed_roblox_folder(expected_version) # pyright: ignore[reportUnknownMemberType]
            if installed_folder:
                return installed_folder

            if status_callback:
                status_callback("Installing Roblox", "Installing Roblox quietly in the background...", "indeterminate")

            time.sleep(0.25)
            self.pump_ui()

        return self.get_installed_roblox_folder() # pyright: ignore[reportUnknownVariableType, reportUnknownMemberType]

    def run_roblox_installer(self, installer_path, expected_version, silent=False, status_callback=None):
        try:
            popen_kwargs = {}
            if silent:
                popen_kwargs.update(self.get_hidden_process_kwargs())

            subprocess.Popen([installer_path], cwd=os.path.dirname(installer_path), **popen_kwargs)
        except Exception as e:
            raise RuntimeError(f"Could not start the Roblox installer.\n{e}") from e

        if status_callback:
            status_callback("Installing Roblox", "Installing Roblox..", "indeterminate")

        print("- Waiting for Roblox installation/update to finish...")
        installed_folder = self.wait_for_roblox_install(expected_version, status_callback=status_callback) # pyright: ignore[reportUnknownArgumentType]
        
        if os.path.exists(self.local_versions_path):
            try:
                import shutil
                shutil.rmtree(self.local_versions_path)
                print("- Cleaned up Roblox Download folder.")
            except Exception as e:
                print(f"- Could not clean up Download folder: {e}")

        if not installed_folder:
            raise RuntimeError("The Roblox installer ran, but VeloStrap could not find RobloxPlayerBeta.exe afterward.")

        return installed_folder

    def ensure_roblox_installation(self, allow_download=True, show_errors=True, status_callback=None, silent_install=False):
        installed_folder = self.get_installed_roblox_folder() # pyright: ignore[reportUnknownVariableType, reportUnknownMemberType]

        if status_callback:
            status_callback("Checking Roblox", "Checking for the latest Roblox version...", "indeterminate")

        try:
            live_version = self.get_live_roblox_version()
            print(f"- Roblox live version detected: {live_version}")
        except Exception as e:
            print(f"- Could not check Roblox live version: {e}")
            if installed_folder:
                if status_callback:
                    status_callback("Launching Roblox", "Could not check Roblox's live version. Launching the installed build...", "indeterminate")
                return installed_folder

            if show_errors:
                self.close_activity_window()
                messagebox.showerror("Roblox Missing", "VeloStrap could not find Roblox and also could not reach Roblox's version API.")
            return None

        exact_live_folder = self.find_installed_roblox_folder(live_version) # pyright: ignore[reportUnknownMemberType]
        if exact_live_folder:
            return exact_live_folder

        if not installed_folder:
            installed_folder = self.get_current_installed_roblox_folder() # pyright: ignore[reportUnknownVariableType, reportUnknownMemberType]

        if installed_folder and os.path.basename(installed_folder).lower() == live_version.lower(): # pyright: ignore[reportUnknownMemberType, reportUnknownArgumentType]
            return installed_folder

        if not allow_download and installed_folder:
            return installed_folder

        try:
            installer_path = self.download_roblox_installer(live_version, status_callback=status_callback) # pyright: ignore[reportUnknownVariableType, reportUnknownMemberType]
            return self.run_roblox_installer(installer_path, live_version, silent=silent_install, status_callback=status_callback) # pyright: ignore[reportUnknownVariableType, reportUnknownMemberType]
        except Exception as e:
            print(f"- Roblox auto-download/update failed: {e}")
            if installed_folder:
                print("- Falling back to the currently installed Roblox build.")
                if status_callback:
                    status_callback("Launching Roblox", "Roblox could not update cleanly, so VeloStrap is launching the installed build...", "indeterminate")
                return installed_folder

            if show_errors:
                self.close_activity_window()
                messagebox.showerror("Roblox Download Failed", str(e))
            return None

    def get_mac_roblox_app_path(self):
        return "/Applications/Roblox.app"

    def get_mac_roblox_executable(self):
        return os.path.join(self.get_mac_roblox_app_path(), "Contents", "MacOS", "RobloxPlayer")

    def get_mac_fastflags_root(self):
        return os.path.expanduser("~/Library/Application Support/Roblox")

    def get_linux_sober_config_file(self):
        return os.path.expanduser(f"~/.var/app/{SOBER_FLATPAK_ID}/config/sober/config.json")

    def download_mac_roblox_dmg(self, status_callback=None):
        cache_root = os.path.join(self.ensure_local_versions_root(), "macos")
        os.makedirs(cache_root, exist_ok=True)
        destination = os.path.join(cache_root, "Roblox.dmg")

        if os.path.exists(destination) and os.path.getsize(destination) > 0:
            if status_callback:
                status_callback("Downloading Roblox", "Using the cached macOS Roblox installer...", "indeterminate")
            print(f"- Reusing cached macOS installer: {destination}")
            return destination

        if status_callback:
            status_callback("Downloading Roblox", "Downloading the official Roblox Mac installer...", "indeterminate")

        print(f"- Downloading Roblox for macOS from {ROBLOX_MAC_DOWNLOAD_URL}")
        try:
            with requests.get(ROBLOX_MAC_DOWNLOAD_URL, stream=True, timeout=(15, 60)) as response:
                response.raise_for_status()
                total_bytes = int(response.headers.get("content-length", "0") or 0)
                downloaded_bytes = 0

                with open(destination, "wb") as file_handle:
                    for chunk in response.iter_content(chunk_size=DOWNLOAD_CHUNK_SIZE):
                        if not chunk:
                            continue

                        file_handle.write(chunk)
                        downloaded_bytes += len(chunk)
                        if status_callback:
                            if total_bytes > 0:
                                progress_value = min(downloaded_bytes / total_bytes, 1.0)
                                status_callback(
                                    "Downloading Roblox for Mac",
                                    f"Downloading Roblox.. {progress_value:.0%}",
                                    "determinate",
                                    progress_value
                                )
                            else:
                                status_callback("Downloading Roblox for Mac", "Downloading the official Roblox Mac installer...", "indeterminate")
        except Exception:
            if os.path.exists(destination):
                try:
                    os.remove(destination)
                except OSError:
                    pass
            raise

        if not os.path.exists(destination) or os.path.getsize(destination) <= 0:
            raise RuntimeError("The Roblox Mac download finished, but the .dmg file was empty.")

        return destination

    def attach_mac_dmg(self, dmg_path):
        hdiutil_path = shutil.which("hdiutil")
        if not hdiutil_path:
            raise RuntimeError("hdiutil was not found. This installer path only works on macOS.")

        result = subprocess.run(
            [hdiutil_path, "attach", dmg_path, "-nobrowse", "-readonly", "-plist"],
            capture_output=True,
            check=True
        )
        payload = plistlib.loads(result.stdout)

        for entity in payload.get("system-entities", []):
            mount_point = entity.get("mount-point")
            if mount_point:
                print(f"- Mounted Roblox DMG at {mount_point}")
                return mount_point

        raise RuntimeError("Roblox DMG mounted, but no mount point was reported.")

    def detach_mac_dmg(self, mount_point):
        hdiutil_path = shutil.which("hdiutil")
        if not hdiutil_path or not mount_point:
            return

        try:
            subprocess.run([hdiutil_path, "detach", mount_point, "-quiet"], check=False, timeout=30)
            print(f"- Detached Roblox DMG from {mount_point}")
        except Exception as e:
            print(f"- Could not detach Roblox DMG: {e}")

    def find_roblox_app_in_mount(self, mount_point):
        direct_path = os.path.join(mount_point, "Roblox.app")
        if os.path.isdir(direct_path):
            return direct_path

        for root, directory_names, _ in os.walk(mount_point):
            if "Roblox.app" in directory_names:
                return os.path.join(root, "Roblox.app")

        return None

    def install_mac_roblox_from_dmg(self, dmg_path, status_callback=None):
        mount_point = None
        try:
            if status_callback:
                status_callback("Installing Roblox", "Mounting Roblox.dmg...", "indeterminate")
            mount_point = self.attach_mac_dmg(dmg_path)

            source_app = self.find_roblox_app_in_mount(mount_point)
            if not source_app:
                raise RuntimeError("Roblox.app was not found inside the mounted .dmg.")

            target_app = self.get_mac_roblox_app_path()
            if status_callback:
                status_callback("Installing Roblox", "Copying Roblox.app to /Applications/...", "indeterminate")

            shutil.copytree(source_app, target_app, dirs_exist_ok=True)
            print(f"- SUCCESS: Copied Roblox.app to {target_app}")
            return target_app
        finally:
            if mount_point:
                self.detach_mac_dmg(mount_point)

    def ensure_mac_roblox_installation(self, allow_download=True, show_errors=True, status_callback=None):
        app_path = self.get_mac_roblox_app_path()
        exe_path = self.get_mac_roblox_executable()

        if os.path.exists(exe_path):
            return app_path

        if not allow_download:
            if show_errors:
                messagebox.showwarning(
                    "Mac Launch Error",
                    "Mac Launch Error - if you're not on Mac, click OK.\n\nRoblox.app was not found in /Applications/.",
                    parent=self
                )
            return None

        if sys.platform != "darwin":
            if show_errors:
                messagebox.showwarning(
                    "Mac Launch Error",
                    "Mac Launch Error - if you're not on Mac, click OK.\n\nThe macOS installer uses hdiutil and /Applications/Roblox.app.",
                    parent=self
                )
            return None

        try:
            dmg_path = self.download_mac_roblox_dmg(status_callback=status_callback)
            self.install_mac_roblox_from_dmg(dmg_path, status_callback=status_callback)
        except Exception as e:
            print(f"- Roblox macOS install failed: {e}")
            if show_errors:
                self.close_activity_window()
                messagebox.showerror("Roblox Mac Install Failed", str(e), parent=self)
            return None

        if os.path.exists(exe_path):
            return app_path

        if show_errors:
            self.close_activity_window()
            messagebox.showerror(
                "Roblox Mac Install Failed",
                "Roblox.app was copied, but /Applications/Roblox.app/Contents/MacOS/RobloxPlayer was not found.",
                parent=self
            )
        return None

    def get_flatpak_path(self):
        resolved = shutil.which("flatpak")
        if resolved:
            return resolved

        for candidate in FLATPAK_CANDIDATE_PATHS:
            if os.path.isfile(candidate) and os.access(candidate, os.X_OK):
                return candidate

        user_candidate = os.path.expanduser("~/.local/bin/flatpak")
        if os.path.isfile(user_candidate) and os.access(user_candidate, os.X_OK):
            return user_candidate

        return None

    def sober_exists_on_disk(self):
        return os.path.isdir(SOBER_FLATPAK_USER_APP_DIR) or os.path.isdir(SOBER_FLATPAK_SYSTEM_APP_DIR)

    def get_sober_flatpak_scope_args(self, flatpak_path):
        scopes = (["--user"], ["--system"], []) # pyright: ignore[reportUnknownVariableType]
        for scope_args in scopes:
            command = [flatpak_path, "info", *scope_args, SOBER_FLATPAK_ID]
            try:
                result = subprocess.run(
                    command, # pyright: ignore[reportUnknownArgumentType]
                    capture_output=True,
                    text=True,
                    timeout=30,
                )
                if result.returncode == 0:
                    return scope_args
            except Exception as e:
                print(f"- Could not check Sober Flatpak scope {scope_args or 'default'}: {e}")

        if os.path.isdir(SOBER_FLATPAK_USER_APP_DIR):
            return ["--user"]
        if os.path.isdir(SOBER_FLATPAK_SYSTEM_APP_DIR):
            return ["--system"]
        return None

    def ensure_flathub_remote(self, flatpak_path, scope_args=None):
        scope_attempts = [scope_args] if scope_args is not None else [["--user"], []]
        for attempt_scope in scope_attempts:
            command = [flatpak_path, "remote-add", "--if-not-exists", *attempt_scope, "flathub", FLATHUB_REMOTE_URL]
            try:
                subprocess.run(
                    command, # pyright: ignore[reportUnknownArgumentType]
                    capture_output=True,
                    text=True,
                    timeout=120,
                    check=True,
                )
                return True
            except Exception as e:
                print(f"- Could not ensure Flathub remote for scope {attempt_scope or 'default'}: {e}")
        return False

    def is_sober_installed(self, flatpak_path):
        return self.get_sober_flatpak_scope_args(flatpak_path) is not None # pyright: ignore[reportUnknownMemberType]

    def build_sober_install_command(self, flatpak_path, scope_args):
        return [
            flatpak_path,
            "install",
            *scope_args,
            "--assumeyes",
            "--noninteractive",
            "flathub",
            SOBER_FLATPAK_ID,
        ]

    def try_install_sober_flatpak(self, flatpak_path, show_errors=True):
        install_scopes = [["--user"], []]
        last_error = "Unknown Flatpak install error."

        for scope_args in install_scopes:
            if not self.ensure_flathub_remote(flatpak_path, scope_args=scope_args):
                continue

            try:
                self.pump_ui()
                command = self.build_sober_install_command(flatpak_path, scope_args)
                print(f"- Installing Sober with Flatpak: {' '.join(command)}")
                install_result = subprocess.run(
                    command, # pyright: ignore[reportUnknownArgumentType]
                    capture_output=True,
                    text=True,
                    timeout=600,
                    check=True,
                )
                if install_result.stderr:
                    print(install_result.stderr)
                self.pump_ui()
                if self.is_sober_installed(flatpak_path):
                    return True
            except Exception as e:
                print(f"- Sober install failed for scope {scope_args or 'default'}: {e}")
                last_error = str(e)
                if isinstance(e, subprocess.CalledProcessError):
                    last_error = (e.stderr or e.stdout or last_error).strip()

        if show_errors:
            self.close_activity_window()
            messagebox.showerror(
                "Sober Install Failed",
                (
                    "Could not install Sober automatically.\n\n"
                    f"Try running this commmand yourself:\n"
                    f"flatpak install --user flathub {SOBER_FLATPAK_ID}\n\n"
                    f"{last_error}"
                ),
                parent=self,
            )
        return False

    def ensure_sober_installation(self, allow_download=True, show_errors=True, status_callback=None):
        flatpak_path = self.get_flatpak_path()
        if not flatpak_path:
            if show_errors:
                messagebox.showwarning(
                    "Linux Arch Launch Error",
                    (
                        "Linux Arch Launch Error - if you're not on Linux Arch, click OK.\n\n"
                        "Flatpak is not installed. Please install Flatpak for your distribution, add Flathub, "
                        f"then run: flatpak install --user flathub {SOBER_FLATPAK_ID}"
                    ),
                    parent=self
                )
            return None

        if self.is_sober_installed(flatpak_path): # pyright: ignore[reportUnknownMemberType]
            return flatpak_path

        if not allow_download:
            if show_errors:
                messagebox.showwarning(
                    "Linux Arch Launch Error",
                    (
                        "Linux Arch Launch Error - if you're not on Linux Arch, click OK.\n\n"
                        f"Sober is not installed. Run: flatpak install --user flathub {SOBER_FLATPAK_ID}"
                    ),
                    parent=self
                )
            return None

        if status_callback:
            status_callback("Installing Sober", "Installing Sober from Flathub...", "indeterminate")

        if not self.try_install_sober_flatpak(flatpak_path, show_errors=show_errors): # pyright: ignore[reportUnknownMemberType]
            return None

        if self.is_sober_installed(flatpak_path): # pyright: ignore[reportUnknownMemberType]
            return flatpak_path

        if show_errors:
            self.close_activity_window()
            messagebox.showerror("Sober Install Failed", "Flatpak finished, but Sober is still not installed.", parent=self)
        return None

    def ensure_platform_installation(self, os_name, allow_download=True, show_errors=True, status_callback=None, silent_install=False):
        selected_os = self.normalize_selected_os(os_name) # pyright: ignore[reportUnknownMemberType]
        if selected_os == OS_MAC:
            return self.ensure_mac_roblox_installation( # pyright: ignore[reportUnknownMemberType]
                allow_download=allow_download,
                show_errors=show_errors,
                status_callback=status_callback
            )
        if selected_os == OS_LINUX_ARCH:
            return self.ensure_sober_installation( # pyright: ignore[reportUnknownMemberType]
                allow_download=allow_download,
                show_errors=show_errors,
                status_callback=status_callback
            )

        if os.name != "nt":
            if show_errors:
                messagebox.showwarning(
                    "Windows Launch Error",
                    (
                        "Windows Launch Error - if you're not on Windows, click OK.\n\n"
                        "RobloxPlayerBeta.exe uses the Windows local appdata Roblox install path."
                    ),
                    parent=self
                )
            return None

        return self.ensure_roblox_installation( 
            allow_download=allow_download,
            show_errors=show_errors,
            status_callback=status_callback,
            silent_install=silent_install
        ) 

    # ==========================================
    # LAUNCH LOGIC
    # ==========================================
    def start_platform_download(self):
        if not self.check_rate_limit():
            return

        self.save_launcher_data()
        selected_os = self.normalize_selected_os(self.selected_os)
        if self.platform_download_btn:
            self.platform_download_btn.configure(state="disabled", text="Preparing...")

        self.update_activity_window(
            f"Preparing {self.get_os_label(selected_os)}",
            "Checking platform requirements...",
            "indeterminate"
        )

        try:
            install_target = self.ensure_platform_installation(
                selected_os,
                allow_download=True,
                show_errors=True,
                status_callback=self.update_activity_window,
                silent_install=True
            )
            self.close_activity_window()
            if install_target:
                messagebox.showinfo(
                    "Platform Ready",
                    f"{self.get_os_label(selected_os)} setup is ready.",
                    parent=self
                )
        finally:
            if self.platform_download_btn:
                self.platform_download_btn.configure(state="normal", text=self.get_platform_download_button_text())
    
    def save_fast_flags(self):
        self.save_launcher_data()
        self.refresh_fastflag_views(use_current_ui=True)

        selected_os = self.normalize_selected_os(self.selected_os)
        install_target = self.ensure_platform_installation(
            selected_os,
            allow_download=True,
            show_errors=True,
            status_callback=self.update_activity_window,
            silent_install=True
        )
        self.close_activity_window()
        if not install_target:
            return

        try:
            self.write_platform_fast_flags(selected_os, install_target, use_current_ui=True)
        except Exception as e:
            print(f"- FastFlag save failed: {e}")
            log_error(f"Could not save FastFlags: {e}")
            messagebox.showerror("FastFlags Error", f"Could not save FastFlags.\n{e}", parent=self)
            return

        if selected_os == OS_WINDOWS:
            try:
                self.apply_selected_mods(install_target)
            except Exception as e:
                log_error(f"Could not apply selected mods while saving FastFlags: {e}")
                messagebox.showerror("Mods Error", f"FastFlags saved, but some mods could not be applied.\n{e}")

    def build_builtin_fast_flags(self, use_current_ui=False):
        if use_current_ui:
            render = self.ren_var.get()
            alt_enter_fullscreen = bool(self.alt_enter_fullscreen_switch.get()) if hasattr(self, "alt_enter_fullscreen_switch") else False
            texture_quality_mode = self.normalize_texture_quality_mode(
                self.texture_quality_var.get() if hasattr(self, "texture_quality_var") else DEFAULT_TEXTURE_QUALITY_MODE
            )
            msaa_mode = self.normalize_msaa_mode(
                self.msaa_var.get() if hasattr(self, "msaa_var") else DEFAULT_MSAA_MODE
            )
            mesh_quality_level = self.normalize_mesh_quality_level(
                self.mesh_quality_slider.get() if hasattr(self, "mesh_quality_slider") else DEFAULT_MESH_QUALITY_LEVEL
            )
            graphics_quality_override = self.normalize_graphics_quality_override(
                self.graphics_quality_slider.get() if hasattr(self, "graphics_quality_slider") else DEFAULT_GRAPHICS_QUALITY_OVERRIDE
            )
        else:
            render = self.npx_data.get("Rendering Mode", DEFAULT_RENDERING)
            alt_enter_fullscreen = bool(self.npx_data.get("Alt Enter Fullscreen", False))
            texture_quality_mode = self.normalize_texture_quality_mode(
                self.npx_data.get("Texture Quality Mode", DEFAULT_TEXTURE_QUALITY_MODE)
            )
            msaa_mode = self.normalize_msaa_mode(
                self.npx_data.get("MSAA Mode", DEFAULT_MSAA_MODE)
            )
            mesh_quality_level = self.normalize_mesh_quality_level(
                self.npx_data.get("Mesh Quality Level", DEFAULT_MESH_QUALITY_LEVEL)
            )
            graphics_quality_override = self.normalize_graphics_quality_override(
                self.npx_data.get("Graphics Quality Override", DEFAULT_GRAPHICS_QUALITY_OVERRIDE)
            )

        flags = {}
            
        if "Vulkan" in render:
            flags["FFlagDebugGraphicsPreferD3D11"] = False
            flags["FFlagDebugGraphicsPreferVulkan"] = True
            flags["FFlagDebugGraphicsPreferOpenGL"] = False
        elif "OpenGL" in render:
            flags["FFlagDebugGraphicsPreferD3D11"] = False
            flags["FFlagDebugGraphicsPreferVulkan"] = False
            flags["FFlagDebugGraphicsPreferOpenGL"] = True
        else:
            flags["FFlagDebugGraphicsPreferD3D11"] = True
            flags["FFlagDebugGraphicsPreferVulkan"] = False
            flags["FFlagDebugGraphicsPreferOpenGL"] = False

        if alt_enter_fullscreen:
            # Roblox's Alt+Enter fullscreen behavior is enabled by setting this flag to false.
            flags["FFlagHandleAltEnterFullscreenManually"] = False

        texture_quality_value = TEXTURE_QUALITY_FLAG_VALUES.get(texture_quality_mode)
        if texture_quality_value is not None:
            flags["DFFlagTextureQualityOverrideEnabled"] = True
            flags["DFIntTextureQualityOverride"] = texture_quality_value

        msaa_value = MSAA_FLAG_VALUES.get(msaa_mode)
        if msaa_value is not None:
            flags["FIntDebugForceMSAASamples"] = msaa_value

        if graphics_quality_override > 0:
            flags["DFIntDebugFRMQualityLevelOverride"] = graphics_quality_override

        flags.update(MESH_QUALITY_FLAG_PRESETS.get(mesh_quality_level, {}))

        return flags

    def build_fast_flags(self, use_current_ui=False):
        flags = self.build_builtin_fast_flags(use_current_ui=use_current_ui)
        flags.update(self.custom_fast_flags)
        flags = dict(sorted(flags.items(), key=lambda item: item[0].lower()))
        return flags

    def write_fast_flags(self, version_folder, use_current_ui=False):
        target_dir = os.path.join(version_folder, "ClientSettings")
        os.makedirs(target_dir, exist_ok=True)
        settings_file = os.path.join(target_dir, "ClientAppSettings.json")

        with open(settings_file, "w", encoding="utf-8") as file_handle:
            json.dump(self.build_fast_flags(use_current_ui=use_current_ui), file_handle, indent=4)

        print(f"- SUCCESS: Flags applied to {settings_file}")
        return settings_file

    def write_mac_fast_flags(self, use_current_ui=False):
        target_dir = os.path.join(self.get_mac_fastflags_root(), "ClientSettings")
        os.makedirs(target_dir, exist_ok=True)
        settings_file = os.path.join(target_dir, "ClientAppSettings.json")

        with open(settings_file, "w", encoding="utf-8") as file_handle:
            json.dump(self.build_fast_flags(use_current_ui=use_current_ui), file_handle, indent=4)

        print(f"- SUCCESS: Mac FastFlags applied to {settings_file}")
        return settings_file

    def coerce_sober_fflag_value(self, raw_value):
        if isinstance(raw_value, bool):
            return raw_value
        if isinstance(raw_value, int) and not isinstance(raw_value, bool):
            return raw_value
        if isinstance(raw_value, float):
            return raw_value
        if isinstance(raw_value, str):
            lowered = raw_value.strip().lower()
            if lowered == "true":
                return True
            if lowered == "false":
                return False
            if lowered.isdigit() or (lowered.startswith("-") and lowered[1:].isdigit()):
                return int(lowered)
            return raw_value
        return raw_value

    def build_sober_fast_flags(self, use_current_ui=False):
        windows_graphics_flags = {
            "FFlagDebugGraphicsPreferD3D11",
            "FFlagDebugGraphicsPreferVulkan",
            "FFlagDebugGraphicsPreferOpenGL",
        }
        flags = self.build_fast_flags(use_current_ui=use_current_ui)
        for flag_name in windows_graphics_flags:
            flags.pop(flag_name, None)
        return {
            flag_name: self.coerce_sober_fflag_value(flag_value)
            for flag_name, flag_value in flags.items()
        }

    def get_sober_default_config(self):
        return {
            "allow_gamepad_permission": False,
            "close_on_leave": True,
            "discord_rpc_enabled": False,
            "enable_gamemode": True,
            "enable_hidpi": False,
            "server_location_indicator_enabled": False,
            "touch_mode": "off",
            "use_console_experience": False,
            "use_libsecret": False,
            "use_opengl": False,
            "graphics_optimization_mode": "balanced",
            "fflags": {},
        }

    def apply_sober_rendering_config(self, config_payload, use_current_ui=False):
        if use_current_ui:
            render = self.ren_var.get() if hasattr(self, "ren_var") else self.npx_data.get("Rendering Mode", DEFAULT_RENDERING)
        else:
            render = self.npx_data.get("Rendering Mode", DEFAULT_RENDERING)
        config_payload["use_opengl"] = "OpenGL" in str(render)

    def load_sober_config_payload(self, config_file):
        config_payload = self.get_sober_default_config()
        if not os.path.exists(config_file):
            return config_payload

        try:
            with open(config_file, "r", encoding="utf-8") as file_handle:
                raw_text = file_handle.read().strip()
            if not raw_text:
                print(f"- Sober config.json is empty, recreating defaults at {config_file}")
                return config_payload

            loaded_payload = json.loads(raw_text)
            if isinstance(loaded_payload, dict):
                config_payload.update(loaded_payload)
            return config_payload
        except json.JSONDecodeError as e:
            backup_file = f"{config_file}.velostrap.bak"
            try:
                shutil.copy2(config_file, backup_file)
                print(f"- Sober config.json was invalid JSON ({e}); backed up to {backup_file}")
            except Exception as backup_error:
                print(f"- Sober config.json was invalid JSON ({e}); could not back up ({backup_error})")
            return config_payload

    def write_sober_fast_flags(self, use_current_ui=False):
        config_file = self.get_linux_sober_config_file()
        os.makedirs(os.path.dirname(config_file), exist_ok=True)

        config_payload = self.load_sober_config_payload(config_file)

        existing_fflags = config_payload.get("fflags")
        if not isinstance(existing_fflags, dict):
            existing_fflags = {}
        existing_fflags.update(self.build_sober_fast_flags(use_current_ui=use_current_ui))
        config_payload["fflags"] = existing_fflags
        self.apply_sober_rendering_config(config_payload, use_current_ui=use_current_ui)

        with open(config_file, "w", encoding="utf-8") as file_handle:
            json.dump(config_payload, file_handle, indent=4)

        print(f"- SUCCESS: Sober FastFlags applied to {config_file}")
        return config_file

    def write_platform_fast_flags(self, os_name, install_target=None, use_current_ui=False):
        selected_os = self.normalize_selected_os(os_name)
        if selected_os == OS_MAC:
            return self.write_mac_fast_flags(use_current_ui=use_current_ui)
        if selected_os == OS_LINUX_ARCH:
            return self.write_sober_fast_flags(use_current_ui=use_current_ui)

        if not install_target:
            install_target = self.get_current_installed_roblox_folder()
        if not install_target:
            raise RuntimeError("Windows Roblox was not found, so FastFlags could not be written.")
        return self.write_fast_flags(install_target, use_current_ui=use_current_ui)

    def start_launch(self):
        self.save_launcher_data()
        self.launch_btn.configure(state="disabled", text="Preparing Roblox...")
        self.update_activity_window("Checking for Roblox", "Checking for the latest Roblox version...", "indeterminate")

        if self.rpc:
            try:
                self.rpc.update(state="With VeloStrap", details="Playing Roblox", start=int(time.time()))
            except:
                pass

        self.voidstrap_based_installer_but_its_a_launching_sequence_instead_downloading_roblox(0)
        
    def voidstrap_based_installer_but_its_a_launching_sequence_instead_downloading_roblox(self, value):
        self.final_launch()

    def get_host_capable_launch_platforms(self):
        if sys.platform == "linux_arch":
            return [OS_LINUX_ARCH]
        if sys.platform == "darwin":
            return [OS_MAC]
        if os.name == "nt":
            return list(OS_FALLBACK_ORDER)
        return [self.normalize_selected_os(self.selected_os)]

    def get_launch_attempt_order(self):
        selected_os = self.normalize_selected_os(self.selected_os)
        capable = self.get_host_capable_launch_platforms()
        if selected_os in capable:
            return [selected_os] + [platform for platform in capable if platform != selected_os]
        return capable

    def build_platform_launch_error_message(self, os_name, error):
        selected_os = self.normalize_selected_os(os_name)
        if selected_os == OS_MAC:
            prefix = "Mac Launch Error - if you're not on Mac, click OK."
        elif selected_os == OS_LINUX_ARCH:
            prefix = "Linux Arch Launch Error - if you're not on Linux Arch, click OK."
        else:
            prefix = "Windows Launch Error - if you're not on Windows, click OK."

        return f"{prefix}\n\n{error}"

    def show_platform_launch_warning(self, os_name, error):
        self.close_activity_window()
        messagebox.showwarning(
            f"{self.get_os_label(os_name)} Launch Error",
            self.build_platform_launch_error_message(os_name, error),
            parent=self
        )

    def launch_windows_roblox(self):
        if os.name != "nt":
            raise RuntimeError("RobloxPlayerBeta.exe is a Windows executable and the Windows local appdata install path is not available here.")

        if self.npx_data.get("Multi_Instance", False):
            try:
                ctypes.windll.kernel32.CreateMutexW(None, True, ROBLOX_MUTEX_NAME)
                print("- SUCCESS: Multi-Instance Mutex Created!")
            except Exception as e:
                print(f"- Mutex Error: {e}")

        installed_folder = self.ensure_roblox_installation(
            allow_download=True,
            show_errors=False,
            status_callback=self.update_activity_window,
            silent_install=True
        )
        if not installed_folder:
            raise RuntimeError("RobloxPlayerBeta.exe could not be found or installed in the Windows local appdata Roblox Versions folder.")

        self.update_activity_window("Launching Roblox..", "Applying FastFlags and Mods..", "indeterminate")

        try:
            self.write_platform_fast_flags(OS_WINDOWS, installed_folder, use_current_ui=False)
        except Exception as e:
            raise RuntimeError(f"Could not apply Windows FastFlags before launch.\n{e}") from e
        
        try:
            self.apply_selected_mods(installed_folder)
        except Exception as e:
            log_error(f"Could not apply selected mods before launch: {e}")
            self.close_activity_window()
            messagebox.showerror("Mods Error", f"Roblox will still launch, but some mods could not be applied.\n{e}")

        self.update_activity_window("Launching Roblox", "Starting Roblox..", "indeterminate")

        exe = os.path.join(installed_folder, "RobloxPlayerBeta.exe")
        if not os.path.exists(exe):
            raise RuntimeError("RobloxPlayerBeta.exe was not found after the install/update completed.")

        try:
            print(f"- SUCCESS: Found executable at {exe}. Launching...")
            subprocess.Popen([exe])
            print("Taking a few seconds to launch Roblox..")
            self.pump_ui()
            time.sleep(0.5)
            self.safe_close()
        except Exception as e:
            raise RuntimeError(f"Could not start RobloxPlayerBeta.exe.\n{e}") from e

    def launch_mac_roblox(self):
        app_path = self.ensure_mac_roblox_installation(
            allow_download=True,
            show_errors=False,
            status_callback=self.update_activity_window
        )
        exe = self.get_mac_roblox_executable()
        if not app_path or not os.path.exists(exe):
            raise RuntimeError(f"{exe} was not found.")

        self.update_activity_window("Launching Roblox", "Applying FastFlags for Mac (EXPERIMENTAL)..", "indeterminate")
        try:
            self.write_platform_fast_flags(OS_MAC, app_path, use_current_ui=False)
        except Exception as e:
            raise RuntimeError(f"Could not apply Mac FastFlags before launch.\n{e}") from e

        try:
            print(f"- SUCCESS: Found macOS executable at {exe}. Launching...")
            subprocess.Popen([exe])
            self.pump_ui()
            time.sleep(0.5)
            self.safe_close()
        except Exception as e:
            raise RuntimeError(f"Could not start RobloxPlayer on macOS.\n{e}") from e

    def launch_linux_sober(self):
        flatpak_path = self.get_flatpak_path()
        if not flatpak_path:
            raise RuntimeError(
                "Flatpak was not found on this system.\n\n"
                "Install Flatpak for your distribution, then run:\n"
                f"flatpak install --user flathub {SOBER_FLATPAK_ID}"
            )

        if not self.is_sober_installed(flatpak_path):
            flatpak_path = self.ensure_sober_installation(
                allow_download=True,
                show_errors=False,
                status_callback=self.update_activity_window
            )

        scope_args = self.get_sober_flatpak_scope_args(flatpak_path) if flatpak_path else None
        if not flatpak_path or scope_args is None:
            raise RuntimeError(
                f"Sober ({SOBER_FLATPAK_ID}) is not installed.\n\n"
                "Try running:\n"
                f"flatpak install --user flathub {SOBER_FLATPAK_ID}\n\n"
                "If it is already installed, verify with:\n"
                f"flatpak info --user {SOBER_FLATPAK_ID}"
            )

        self.update_activity_window("Launching Sober", "Applying FastFlags for Linux Arch (EXPERIMENTAL)..", "indeterminate")
        try:
            self.write_platform_fast_flags(OS_LINUX_ARCH, flatpak_path, use_current_ui=False)
        except Exception as e:
            raise RuntimeError(f"Could not apply Sober FastFlags before launch.\n{e}") from e

        try:
            launch_command = [flatpak_path, "run", *scope_args, SOBER_FLATPAK_ID]
            print(f"- SUCCESS: Launching Sober with Flatpak: {' '.join(launch_command)}")
            subprocess.Popen(launch_command)
            self.pump_ui()
            time.sleep(0.5)
            self.safe_close()
        except Exception as e:
            raise RuntimeError(f"Could not start Sober.\n{e}") from e

    def launch_platform(self, os_name):
        selected_os = self.normalize_selected_os(os_name)
        if selected_os == OS_MAC:
            return self.launch_mac_roblox()
        if selected_os == OS_LINUX_ARCH:
            return self.launch_linux_sober()
        return self.launch_windows_roblox()

    def final_launch(self):
        errors_by_os = {}
        attempt_order = self.get_launch_attempt_order()

        for index, os_name in enumerate(attempt_order):
            selected_os = self.normalize_selected_os(os_name)
            fallback_text = "" if index == 0 else " fallback"
            self.update_activity_window(
                f"Trying {self.get_os_label(selected_os)}",
                f"Starting{fallback_text} launch path for {self.get_os_label(selected_os)}...",
                "indeterminate"
            )

            try:
                self.launch_platform(selected_os)
                return
            except Exception as e:
                errors_by_os[selected_os] = str(e)
                print(f"- {self.get_os_label(selected_os)} launch attempt failed: {e}")
                self.show_platform_launch_warning(selected_os, e)

            if all(os_value in errors_by_os for os_value in OS_FALLBACK_ORDER):
                break

        self.close_activity_window()
        details = "\n\n".join(
            f"{self.get_os_label(os_value)}:\n{errors_by_os.get(os_value, 'Not attempted.')}"
            for os_value in OS_FALLBACK_ORDER
        )
        messagebox.showerror(
            "Critical Launch Error;",
            f"All VeloStrap launch paths failed:\n\n{details}",
            parent=self
        )
        self.reset_launch_state()
        log_error(f"All VeloStraps launch paths have failed:\n{details}")

    def reset_launch_state(self):
        self.close_activity_window()
        self.launch_btn.configure(state="normal", text=self.get_launch_button_text())
        self.restore_idle_rpc()

    def monitor_and_close(self, proc):
        proc.wait()
        time.sleep(0.5)
        self.after(0, self.safe_close)
        
    def safe_close(self):
        self.stop_rpc()
        self.close_activity_window()
        self.destroy() 
        sys.exit()
        
