if __name__ == "__main__":
    initialize_developer_logging()
    loading_seq()
    run_general_extra_check()
    app = UI() # pyright: ignore[reportUndefinedVariable, reportUnknownVariableType]

    if sys.platform == "linux_arch":
        # Linux Arch Arch tkinter needs an active event loop before modal dialogs are reliable.
        def run_linux_startup():
            if DEVELOPER_MODE:
                print("- Developer Mode: Skipping agreements.")
                app.show_os_selector_if_needed()
                return
            if not agreement(app):  # pyright: ignore[reportUnknownArgumentType]
                app.destroy() # pyright: ignore[reportUnknownMemberType]
                sys.exit()
            app.show_os_selector_if_needed()

        app.after(0, run_linux_startup)
        app.mainloop() # pyright: ignore[reportUnknownMemberType]
    else:
        if DEVELOPER_MODE:
            pass
            print("- Developer Mode: Skipping agreements.")
        else:
            if not agreement(app):  # pyright: ignore[reportUnknownArgumentType]
                  app.destroy() # pyright: ignore[reportUnknownMemberType]
                  sys.exit()

        app.show_os_selector_if_needed()
        app.mainloop() # pyright: ignore[reportUnknownMemberType]
